// ─── File: ResilientGatewayDemo.java ───
// Demonstrates retry, circuit breaker, cache fallback when a service is down.
package com.bank.gateway.demo;

import java.math.BigDecimal;
import java.util.logging.*;

public class ResilientGatewayDemo {
    private static final Logger log = Logger.getLogger("ResilientGateway");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new RgLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        BalanceService service = new BalanceService();
        BalanceGateway gateway = new BalanceGateway(service);

        log.info("=== Phase 1: service healthy ===");
        for (int i = 0; i < 2; i++) show(gateway);

        log.info("=== Phase 2: transient blip (retry recovers) ===");
        service.setMode(BalanceService.Mode.BLIP);
        show(gateway);

        log.info("=== Phase 3: sustained outage (breaker opens, cache fallback) ===");
        service.setMode(BalanceService.Mode.DOWN);
        for (int i = 0; i < 6; i++) { show(gateway); Thread.sleep(300); }

        log.info("=== Phase 4: recovered (half-open closes) ===");
        service.setMode(BalanceService.Mode.HEALTHY);
        Thread.sleep(2000);
        show(gateway);
    }

    private static void show(BalanceGateway g) {
        BigDecimal bal = g.getBalance("SAV2001");
        log.info(() -> "Rajesh balance served = Rs." + bal);
    }
}

// ─── Would be in client/BalanceService.java ───
class BalanceService {
    enum Mode { HEALTHY, BLIP, DOWN }
    private Mode mode = Mode.HEALTHY;
    private int blipCounter = 0;
    void setMode(Mode m) { this.mode = m; this.blipCounter = 0; }

    BigDecimal getBalance(String accountId) {
        switch (mode) {
            case DOWN:
                throw new RuntimeException("BalanceService DOWN");
            case BLIP:
                blipCounter++;
                if (blipCounter < 2) throw new RuntimeException("BalanceService transient blip");
                return new BigDecimal("1000000.00");
            default:
                return new BigDecimal("1000000.00");
        }
    }
}

// ─── Would be in resilience/BalanceCache.java ───
class BalanceCache {
    private final java.util.Map<String, BigDecimal> cache = new java.util.HashMap<>();
    void put(String id, BigDecimal v) { cache.put(id, v); }
    BigDecimal get(String id) { return cache.getOrDefault(id, BigDecimal.ZERO); }
}

