class CircuitBreaker {
    private static final Logger log = Logger.getLogger("ResilientGateway");
    enum State { CLOSED, OPEN, HALF_OPEN }
    private State state = State.CLOSED;
    private int failures = 0;
    private final int threshold;
    private long openedAt = 0;
    private final long coolDownMs;

    CircuitBreaker(int threshold, long coolDownMs) { this.threshold = threshold; this.coolDownMs = coolDownMs; }

    boolean allowRequest() {
        if (state == State.OPEN) {
            if (System.currentTimeMillis() - openedAt >= coolDownMs) {
                state = State.HALF_OPEN;
                log.warning("Circuit HALF_OPEN — trial call allowed");
                return true;
            }
            return false; // fail fast
        }
        return true;
    }

    void recordSuccess() {
        if (state == State.HALF_OPEN) log.info("Circuit CLOSED — service recovered");
        state = State.CLOSED; failures = 0;
    }

    void recordFailure() {
        failures++;
        if (failures >= threshold || state == State.HALF_OPEN) {
            state = State.OPEN; openedAt = System.currentTimeMillis();
            log.severe(() -> "Circuit OPEN after " + failures + " failures");
        }
    }

    State getState() { return state; }
}

// ─── Would be in core/BalanceGateway.java ───
class BalanceGateway {
    private static final Logger log = Logger.getLogger("ResilientGateway");
    private final BalanceService service;
    private final CircuitBreaker breaker = new CircuitBreaker(3, 1500);
    private final BalanceCache cache = new BalanceCache();

    BalanceGateway(BalanceService service) { this.service = service; }

    BigDecimal getBalance(String accountId) {
        // 1) Circuit breaker: fail fast if open.
        if (!breaker.allowRequest()) {
            log.warning("Breaker OPEN — serving cached fallback without calling service");
            return cache.get(accountId);
        }
        // 2) Bounded retry with backoff for transient blips.
        int attempts = 3; long wait = 100;
        for (int i = 1; i <= attempts; i++) {
            try {
                BigDecimal bal = service.getBalance(accountId);
                breaker.recordSuccess();
                cache.put(accountId, bal); // refresh cache on success
                return bal;
            } catch (RuntimeException ex) {
                log.warning("Attempt " + i + " failed: " + ex.getMessage());
                if (i == attempts) {
                    breaker.recordFailure();
                    log.severe("All retries failed — serving cached fallback");
                    return cache.get(accountId); // 3) fallback
                }
                sleep(wait); wait *= 2; // exponential backoff
            }
        }
        return cache.get(accountId);
    }

    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

